function is_https(){ if(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off') return true; $tp=array_filter(array_map('trim',explode(',',(string)setting('trusted_proxies','')))); return strtolower((string)($_SERVER['HTTP_X_FORWARDED_PROTO']??''))==='https'&&in_array((string)($_SERVER['REMOTE_ADDR']??''),$tp,true); }
function base_url(){ return (is_https()?'https':'http').'://'.($_SERVER['HTTP_HOST']??'localhost').rtrim(str_replace('\\','/',dirname($_SERVER['SCRIPT_NAME']??'/')),'/').'/'; }
if(PHP_SAPI!=='cli'){ $sh=max(0,(int)setting('session_hours',0)); if($sh>0){ $sl=$sh*3600; ini_set('session.gc_maxlifetime',(string)$sl); $sd=sys_get_temp_dir().'/vmmon_sessions'; if(!is_dir($sd)) @mkdir($sd,0700,true); if(is_dir($sd)&&is_writable($sd)) session_save_path($sd); session_set_cookie_params(['lifetime'=>$sl,'path'=>'/','secure'=>is_https(),'httponly'=>true,'samesite'=>'Lax']); } else session_set_cookie_params(['path'=>'/','secure'=>is_https(),'httponly'=>true,'samesite'=>'Lax']); header('X-Frame-Options: SAMEORIGIN'); header('X-Content-Type-Options: nosniff'); header('Referrer-Policy: same-origin'); session_start(); } else $_SESSION=[];
// Anslutningen kontrolleras högst var 5:e sekund; efter t.ex. en omstart av MariaDB kopplar långkörande processer (recv, worker, zbx) upp sig igen av sig själva.
function db(){static $p,$chk=0; $now=time(); if($p!==null&&$now-$chk>=5){ $chk=$now; try{ $p->query('SELECT 1')->closeCursor(); }catch(Throwable $e){ $p=null; } }
 if($p===null){ $n=new PDO(DB_DSN,DB_USER,DB_PASS,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]); db_tz($n); $p=$n; $chk=$now; } return $p; }
// Databasens NOW() ska visa samma tid som PHP (annars blandas databasens tidszon, ofta UTC, med PHP:s lokala tid). Sätts per anslutning efter PHP:s UTC-förskjutning, och uppdateras vid sommar-/vintertid.
function db_tz($p=null){ static $last=null; $o=date('P'); if($o===$last) return; try{ ($p??db())->exec("SET time_zone='$o'"); $last=$o; }catch(Throwable $e){} }
function h($s){return htmlspecialchars((string)$s,ENT_QUOTES);}
// Misslyckas läsningen (t.ex. databasen startar om) behålls de senast lästa inställningarna i stället för att alla blir standardvärden – annars stänger lyssnarna sina portar av sig själva.
function setting($k,$d='',$reset=false){ static $s=null,$last=[]; if($reset) $s=null; if($s===null){ $s=[]; try{ foreach(db()->query('SELECT k,v FROM settings') as $r)$s[$r['k']]=$r['v']; $last=$s; }catch(Throwable $e){ $s=$last; } } return $s[$k]??$d; }
function set_setting($k,$v){ db()->prepare('INSERT INTO settings(k,v) VALUES(?,?) ON DUPLICATE KEY UPDATE v=VALUES(v)')->execute([$k,(string)$v]); }
function client_ip(){ $ra=(string)($_SERVER['REMOTE_ADDR']??''); $tp=array_filter(array_map('trim',explode(',',(string)setting('trusted_proxies','')))); if($ra===''||!$tp||!in_array($ra,$tp,true)) return $ra;
 $x=trim((string)($_SERVER['HTTP_X_FORWARDED_FOR']??'')); if($x!==''){ $l=array_reverse(array_map('trim',explode(',',$x))); foreach($l as $ip){ if(!in_array($ip,$tp,true)&&filter_var($ip,FILTER_VALIDATE_IP)) return $ip; } }
 $r=trim((string)($_SERVER['HTTP_X_REAL_IP']??'')); return filter_var($r,FILTER_VALIDATE_IP)?$r:$ra; }
function lang(){ if(isset($GLOBALS['force_lang'])) return $GLOBALS['force_lang']; $l=$_SESSION['lang']??$_COOKIE['lang']??'en'; return $l==='sv'?'sv':'en'; }
function t($sv,$en){ return lang()==='en'?$en:$sv; }
function is_admin(){return ($_SESSION['u']['role']??'')==='admin';}
function mfa_ok(){ if(!empty($_SESSION['sso'])) return true; if(!empty($_SESSION['mfa_t'])&&time()-$_SESSION['mfa_t']<120) return true; try{ $q=db()->prepare('SELECT (totp_enabled=1 AND totp_secret IS NOT NULL) OR EXISTS(SELECT 1 FROM user_passkeys p WHERE p.user_id=users.id) FROM users WHERE id=?'); $q->execute([$_SESSION['u']['id']]); $ok=(bool)$q->fetchColumn(); }catch(Throwable $e){ return true; } if($ok) $_SESSION['mfa_t']=time(); return $ok; }
function need_login($admin=false){ $sh=(int)setting('session_hours',0); if(!empty($_SESSION['u'])&&$sh>0){ if(empty($_SESSION['login_t'])) $_SESSION['login_t']=time(); elseif(time()-(int)$_SESSION['login_t']>$sh*3600){ try{ db()->prepare('UPDATE users SET logged_in=0 WHERE id=?')->execute([$_SESSION['u']['id']]); }catch(Throwable $e){} $_SESSION=[]; } } if(empty($_SESSION['u'])){header('Location: '.(strpos($_SERVER['SCRIPT_NAME'],'/api/')!==false?'../':'').'login.php');exit;} if(setting('enforce_2fa','0')==='1'&&!in_array(basename($_SERVER['SCRIPT_NAME']),['profile.php','passkey.php','logout.php','lang.php'],true)&&!mfa_ok()){ if(strpos($_SERVER['SCRIPT_NAME'],'/api/')!==false){ http_response_code(403); header('Content-Type: application/json'); exit('{"error":"2fa_required"}'); } header('Location: profile.php?need2fa=1'); exit; } if($admin&&!is_admin()){http_response_code(403);exit(t('Endast admin','Admins only'));}}
function need_write(){ if(!is_admin()){ http_response_code(403); exit(t('Du har bara läsbehörighet.','You have read-only access.')); } }
function csrf(){return $_SESSION['t']??=bin2hex(random_bytes(16));}
function csrf_field(){return '<input type="hidden" name="t" value="'.csrf().'">';}
function csrf_check(){ if($_SERVER['REQUEST_METHOD']==='POST' && !hash_equals(csrf(),$_POST['t']??'')){http_response_code(400);exit(empty($_COOKIE[session_name()])?'CSRF – '.t('webbläsaren skickade ingen sessionskaka. Öppna sidan via samma adress (http/https) som servern använder, och tillåt cookies.','the browser sent no session cookie. Open the page using the same address (http/https) the server uses, and allow cookies.'):'CSRF – '.t('sidan har gått ut. Ladda om sidan och försök igen.','the page has expired. Reload the page and try again.'));}}
function flash(){ if(!empty($_SESSION['flash'])){ echo '<p class="card flash">'.h($_SESSION['flash']).'</p>'; unset($_SESSION['flash']); } }
